let currentProjects = [];let activeTab = 'tab-projects';function validateProject(project){const required = ['name','description','url'];const missing = required.filter(field => !project[field]);if(missing.length > 0){console.warn(`Project missing required fields:${missing.join(',')}`,project);return false;}try{new URL(project.url);}catch(error){console.warn(`Project has invalid URL:${project.url}`,project);return false;}return true;}async function loadProjects(){try{const response = await fetch('projects.json');if(!response.ok){throw new Error(`HTTP error:${response.status}`);}const data = await response.json();if(!data || typeof data !== 'object'){throw new Error('Invalid data format:expected object');}if(!Array.isArray(data.projects)){throw new Error('Invalid data format:projects must be an array');}const validProjects = data.projects.filter(validateProject);if(validProjects.length < data.projects.length){console.warn(`Filtered out ${data.projects.length - validProjects.length}invalid projects`);}return{projects:validProjects,lastUpdated:data.lastUpdated};}catch(error){console.error('Failed to load projects:',error);displayErrorMessage('Unable to load projects. Please try again later.');return{projects:[]};}}function displayErrorMessage(message){const container = document.getElementById('project-grid');if(container){container.innerHTML = ` <div class="error-message" role="alert"> <p>${message}</p> </div> `;}}function isValidNavigationURL(url){try{const urlObject = new URL(url);return urlObject.protocol === 'http:' || urlObject.protocol === 'https:';}catch(error){return false;}}function safeNavigate(url,cardElement){if(!isValidNavigationURL(url)){console.error('Navigation error:Invalid URL',url);displayNavigationError(cardElement,'Invalid URL');return false;}try{window.open(url,'_blank','noopener,noreferrer');return true;}catch(error){console.error('Navigation error:',error,'URL:',url);displayNavigationError(cardElement,'Failed to open link');return false;}}function displayNavigationError(cardElement,errorMessage){cardElement.classList.add('error');let errorElement = cardElement.querySelector('.project-card-error');if(!errorElement){errorElement = document.createElement('div');errorElement.className = 'project-card-error';errorElement.setAttribute('role','alert');cardElement.appendChild(errorElement);}errorElement.textContent = `⚠ ${errorMessage}`;setTimeout(()=>{cardElement.classList.remove('error');if(errorElement && errorElement.parentNode){errorElement.remove();}},5000);}function renderProjectCard(project){const card = document.createElement('div');card.className = 'project-card';card.setAttribute('tabindex','0');card.setAttribute('role','listitem');card.setAttribute('aria-label',`Project:${project.name}`);if(project.theme){if(project.theme.primary){card.style.setProperty('--project-primary',project.theme.primary);}if(project.theme.background){card.style.setProperty('--project-bg',project.theme.background);}}const descriptionId = `project-desc-${project.name.toLowerCase().replace(/\s+/g,'-')}`;if(project.image){const imageContainer = document.createElement('div');imageContainer.className = 'project-card-image';const img = document.createElement('img');img.src = project.image;img.alt = `${project.name}preview`;img.loading = 'lazy';img.onerror = function(){imageContainer.style.display = 'none';};imageContainer.appendChild(img);card.appendChild(imageContainer);}const title = document.createElement('h3');title.textContent = project.name;card.appendChild(title);const description = document.createElement('p');description.textContent = project.description;description.id = descriptionId;card.appendChild(description);card.setAttribute('aria-describedby',descriptionId);const linksContainer = document.createElement('div');linksContainer.className = 'project-card-links';if(project.liveDemo){const liveDemoLink = document.createElement('a');liveDemoLink.href = project.liveDemo;liveDemoLink.innerHTML = '<i data-lucide="external-link" class="w-4 h-4"></i> Live Demo';liveDemoLink.className = 'project-link-demo';liveDemoLink.setAttribute('target','_blank');liveDemoLink.setAttribute('rel','noopener noreferrer');liveDemoLink.setAttribute('aria-label',`View live demo of ${project.name}`);liveDemoLink.addEventListener('click',(e)=>{e.stopPropagation();e.preventDefault();safeNavigate(project.liveDemo,card);});linksContainer.appendChild(liveDemoLink);}const repoLink = document.createElement('a');repoLink.href = project.url;repoLink.innerHTML = '<i data-lucide="github" class="w-4 h-4"></i> Repository';repoLink.className = 'project-link-repo';repoLink.setAttribute('target','_blank');repoLink.setAttribute('rel','noopener noreferrer');repoLink.setAttribute('aria-label',`View ${project.name}repository`);repoLink.addEventListener('click',(e)=>{e.stopPropagation();e.preventDefault();safeNavigate(project.url,card);});linksContainer.appendChild(repoLink);card.appendChild(linksContainer);if(project.tags && Array.isArray(project.tags)&& project.tags.length > 0){const tagsContainer = document.createElement('div');tagsContainer.className = 'project-card-tags';project.tags.forEach(tag =>{const tagElement = document.createElement('span');tagElement.className = 'project-card-tag';tagElement.textContent = tag;tagsContainer.appendChild(tagElement);});card.appendChild(tagsContainer);}card.addEventListener('click',()=>{const targetUrl = project.liveDemo || project.url;safeNavigate(targetUrl,card);});card.addEventListener('keydown',(e)=>{if(e.key === 'Enter' || e.key === ' '){e.preventDefault();const targetUrl = project.liveDemo || project.url;safeNavigate(targetUrl,card);}});return card;}function renderAllProjects(projects){const container = document.getElementById('project-grid');if(!container){console.error('Project grid container not found');return;}container.innerHTML = '';projects.forEach((project,index)=>{const card = renderProjectCard(project);card.style.animationDelay = `${index * 0.1}s`;container.appendChild(card);});}function initTheme(){console.log('Initializing theme...');const savedTheme = localStorage.getItem('theme');const prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme:dark)').matches;if(savedTheme === 'dark' ||(!savedTheme && prefersDark)){console.log('Setting initial theme to dark');document.body.classList.add('dark-theme');}else{console.log('Setting initial theme to light');document.body.classList.remove('dark-theme');}const themeToggleBtn = document.getElementById('theme-toggle');if(themeToggleBtn){console.log('Found theme toggle button,attaching listener');themeToggleBtn.removeEventListener('click',toggleTheme);themeToggleBtn.addEventListener('click',toggleTheme);}else{console.warn('Theme toggle button not found in DOM');}}function toggleTheme(event){console.log('Theme toggle clicked');if(event){event.preventDefault();event.stopPropagation();}document.body.classList.toggle('dark-theme');const isDark = document.body.classList.contains('dark-theme');localStorage.setItem('theme',isDark ? 'dark':'light');console.log(`Theme toggled to:${isDark ? 'dark':'light'}`);if(window.lucide){window.lucide.createIcons();}}async function initShowroom(){try{initTheme();initTabs();const data = await loadProjects();currentProjects = data.projects || [];if(activeTab === 'tab-projects'){if(currentProjects.length > 0){renderAllProjects(currentProjects);}else{displayErrorMessage('No projects available to display.');}}else{renderMCPShowcase();}if(window.lucide){window.lucide.createIcons();}}catch(error){console.error('Failed to initialize showroom:',error);displayErrorMessage('Failed to initialize the showroom. Please refresh the page.');}}function initTabs(){const tabs = document.querySelectorAll('.tab-btn');tabs.forEach(tab =>{tab.addEventListener('click',()=>{const tabId = tab.id;if(tabId === activeTab)return;tabs.forEach(t =>{t.classList.remove('active');t.setAttribute('aria-selected','false');});tab.classList.add('active');tab.setAttribute('aria-selected','true');activeTab = tabId;handleTabSwitch(tabId);});});}function handleTabSwitch(tabId){const container = document.getElementById('project-grid');if(!container)return;container.innerHTML = '';if(tabId === 'tab-projects'){if(currentProjects.length > 0){renderAllProjects(currentProjects);}else{displayErrorMessage('No projects available to display.');}}else if(tabId === 'tab-mcp'){renderMCPShowcase();}if(window.lucide){window.lucide.createIcons();}}function renderMCPShowcase(){const container = document.getElementById('project-grid');if(!container)return;const placeholder = document.createElement('div');placeholder.className = 'mcp-placeholder';placeholder.innerHTML = ` <i data-lucide="blocks"></i> <h2>Model Context Protocol Hub</h2> <p>A specialized ecosystem for connecting LLMs to local tools,databases,and APIs. This space will showcase custom MCP servers,prompts,and context engineering tools.</p> <p style="margin-top:1rem;font-weight:600;color:var(--color-accent-blue);">Coming Soon:Integrated Tools Registry</p> `;container.appendChild(placeholder);}if(document.readyState === 'loading'){document.addEventListener('DOMContentLoaded',initShowroom);}else{initShowroom();}